  "/api/support/delivery/{provider}": {
    "post": {
      "tags": [
        "Support"
      ],
      "summary": "Delivery, bounce, and engagement webhook",
      "description": "Provider-agnostic. Returns 200 for everything it deliberately did not act on - a duplicate event, one that cannot be correlated to a message this app sent, or an engagement event (open/click/complaint) Stage 04 only records - because a 4xx makes a provider retry indefinitely. Processing failures return a retryable 500. Only a failed signature is a 401.\n",
      "operationId": "receiveSupportDeliveryEvent",
      "security": [],
      "parameters": [
        {
          "in": "path",
          "name": "provider",
          "required": true,
          "schema": {
            "type": "string",
            "enum": [
              "postmark",
              "mailgun"
            ]
          }
        }
      ],
      "responses": {
        "200": {
          "description": "Accepted",
          "or deliberately ignored": null
        },
        "401": {
          "description": "Signature verification failed"
        },
        "404": {
          "description": "Unknown provider"
        },
        "429": {
          "description": "Rate limited"
        },
        "500": {
          "description": "Processing failed; provider should retry"
        }
      }
    }
  },
  "/api/support/inbound/{provider}": {
    "post": {
      "tags": [
        "Support"
      ],
      "summary": "Inbound email webhook",
      "description": "Provider-agnostic intake. Returns 200 for everything it has deliberately decided not to act on - duplicate deliveries, unknown recipients, teams with support disabled - because a 4xx makes a mail provider retry the same message indefinitely. Processing failures return 500 so the provider retries a recorded, reclaimable event.\n",
      "operationId": "receiveSupportInboundEmail",
      "security": [],
      "parameters": [
        {
          "in": "path",
          "name": "provider",
          "required": true,
          "schema": {
            "type": "string",
            "enum": [
              "postmark",
              "mailgun"
            ]
          }
        }
      ],
      "responses": {
        "200": {
          "description": "Accepted",
          "or deliberately ignored": null
        },
        "401": {
          "description": "Signature or credential verification failed"
        },
        "404": {
          "description": "Unknown provider"
        },
        "429": {
          "description": "Rate limited"
        },
        "500": {
          "description": "Recorded processing failure; retry requested"
        }
      }
    }
  },
